INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am2_l33',2,5,33,'Out of the darkness','冲出黑暗','方向 / 位置介词短语(回答 Where / Which direction:to/from、into/out of、for、towards、at,KS9 扩展)主考 + on + 动名词(= as soon as ''一…就…'')/ that 引导定语从句(可省略)辅考·课文①类','几乎过了一个星期,那姑娘才能讲述自己的遭遇。一天下午,她乘小船从海岸出发,遇上了暴风雨;天将黑时小船撞上一块礁石,姑娘跳进海里,在水里泡了整整一夜才游到岸边——那段时间她游了8英里。第二天凌晨,她看到前方有灯光,知道自己已接近岸边(灯光高悬在峭壁上)。一到岸边,她就朝灯光挣扎着爬上峭壁。她记得的就是这些。第二天醒来,她发现自己躺在医院里。','{"q":"Listen and answer — Why was the girl in the hospital?","options":["She was caught in a storm at sea and swam to shore, exhausted","She had fallen off a cliff","She had a car accident","She was simply seasick"],"answer_index":0}'::jsonb,'{"title":"方向与位置的介词短语","intro":"回答 Where / Which direction 的问题,常用介词短语:to / from(去向/来源)、into / out of(进入/出来)、for(前往)、towards(朝…方向)、at(对着一点)。全用本课和 Key structures 的句子举例。","table":{"headers":["介词","例子"],"rows":[["to / from → 去向 / 来源","He flew to Washington from Chicago."],["into / out of → 进入 / 出来","She jumped into the sea. / out of the window."],["for → 前往","We set out for the village."],["towards → 朝…方向","She swam towards the shore."],["at → 对着一点","The boy threw a stone at a dog."]]},"specialRules":[{"rule":"on + 动名词 = as soon as 引导的时间状语,''一…就…'':On arriving at the shore, she struggled up.","mark":"on + doing"},{"rule":"that 引导定语从句修饰前面的名词,作宾语时常省略:That was all (that) she remembered.","mark":"that 定从(可省)"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',1,NULL,'Nearly a week passed before the girl was able to explain what had happened to her.','几乎过了一个星期,那姑娘才能讲述发生在她身上的事。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',2,NULL,'One afternoon she set out from the coast in a small boat and was caught in a storm.','一天下午,她乘一条小船从海岸出发,遇上了暴风雨。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',3,NULL,'Toward evening, the boat struck a rock and the girl jumped into the sea.','傍晚时分,小船撞上一块礁石,姑娘跳进了海里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',4,NULL,'Then she swam to shore after spending the whole night in the water.','然后她在水里泡了整整一夜,才游到岸边。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',5,NULL,'During that time she covered a distance of eight miles.','在那段时间里,她游了8英里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',6,NULL,'Early next morning, she saw a light ahead.','第二天凌晨,她看到前方有一盏灯。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',7,NULL,'She knew she was near the shore because the light was high up on the cliffs.','她知道自己已接近岸边,因为那灯光高悬在峭壁上。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',8,NULL,'On arriving at the shore, the girl struggled up the cliff toward the light she had seen.','一到岸边,姑娘就朝着她看到的灯光挣扎着爬上峭壁。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',9,NULL,'That was all she remembered.','她所记得的就是这些。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am2_l33',10,NULL,'When she woke up a day later, she found herself in the hospital.','第二天她醒来时,发现自己躺在医院里。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
