INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l33','set out','',NULL,'/set aʊt/','She set out from the coast in a small boat.','她乘小船从海岸出发。','We set out early in the morning.','我们一早就出发了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l33','be caught in a storm','',NULL,'/bi kɔːt ɪn ə stɔːrm/','The boat was caught in a storm.','小船遇上了暴风雨。','We were caught in the rain.','我们淋了雨。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l33','struggle up','',NULL,'/ˈstrʌɡəl ʌp/','The girl struggled up the cliff.','姑娘挣扎着爬上峭壁。','He struggled up the stairs.','他挣扎着爬上楼梯。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am2_l33','a distance of ... miles','',NULL,'/ə ˈdɪstəns əv/','She covered a distance of eight miles.','她游了8英里的距离。','a distance of two miles','两英里的距离') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp1','choice','{"stem":"\"He flew ___ Washington last night.\"(表示去往某地)","options":["to","of","from","at"],"answer_index":0,"stem_cn":"昨晚他飞往华盛顿。","explanation_cn":"表示去往某地,用 to。✓ He flew to Washington 他飞往华盛顿。✗ from:表来源,方向相反;✗ at:表对着一点;✗ of:表所属。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp1','choice','{"stem":"\"She set out ___ the coast in a small boat.\"(表示从某处出发)","options":["to","at","from","into"],"answer_index":2,"stem_cn":"她乘小船从海岸出发。","explanation_cn":"表示从某处出发、来源,用 from。✓ She set out from the coast 她从海岸出发。✗ to:表去向;✗ at:对着一点;✗ into:进入里面。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp1','choice','{"stem":"\"He will be flying from Washington ___ Chicago.\"(from … 搭配,表示到某地)","options":["to","from","of","at"],"answer_index":0,"stem_cn":"他将从华盛顿飞往芝加哥。","explanation_cn":"from … to … 搭配,表示到某地,用 to。✓ from Washington to Chicago 从华盛顿到芝加哥。✗ from:前面已有 from;✗ at:对着一点;✗ of:表所属。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp2','choice','{"stem":"\"The girl jumped ___ the sea.\"(表示跳进…里面)","options":["at","into","out of","for"],"answer_index":1,"stem_cn":"姑娘跳进了海里。","explanation_cn":"表示跳进…里面,用 into。✓ jumped into the sea 跳进海里。✗ out of:向外相反;✗ for:前往;✗ at:对着一点。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp2','choice','{"stem":"\"I threw the paper ___ the window.\"(表示扔到…外面)","options":["into","at","for","out of"],"answer_index":3,"stem_cn":"我把纸扔到了窗外。","explanation_cn":"表示扔到…外面、从里出来,用 out of。✓ threw the paper out of the window 把纸扔出窗外。✗ into:进入相反;✗ for:前往;✗ at:对着一点。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp3','choice','{"stem":"\"We set out ___ the village at six o''clock.\"(表示前往某地)","options":["for","at","into","of"],"answer_index":0,"stem_cn":"6点我们出发去那个村子。","explanation_cn":"set out for = 出发前往某地,用 for。✓ set out for the village 出发去村子。✗ at:对着一点;✗ of:表所属;✗ into:进入里面。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp3','choice','{"stem":"\"George has left ___ Scotland.\"(表示动身去某地)","options":["of","for","out of","at"],"answer_index":1,"stem_cn":"乔治已动身去苏格兰。","explanation_cn":"leave for = 动身去某地,用 for。✓ left for Scotland 动身去苏格兰。✗ at:对着一点;✗ of:表所属;✗ out of:向外。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp4','choice','{"stem":"\"She swam ___ the shore.\"(表示朝…方向)","options":["of","from","towards","at"],"answer_index":2,"stem_cn":"她朝岸边游去。","explanation_cn":"表示朝…方向移动,用 towards。✓ swam towards the shore 朝岸边游去。✗ at:对着一个固定点;✗ of:表所属;✗ from:表来源。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp4','choice','{"stem":"\"The car came ___ me.\"(表示朝…方向)","options":["out of","at","of","towards"],"answer_index":3,"stem_cn":"汽车朝我开来。","explanation_cn":"表示朝…方向,用 towards。✓ The car came towards me 汽车朝我开来。✗ at:对着一点;✗ of:表所属;✗ out of:向外。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp5','choice','{"stem":"\"The boy threw a stone ___ a dog.\"(表示对着一个目标点)","options":["at","into","to","for"],"answer_index":0,"stem_cn":"男孩用石头打狗。","explanation_cn":"表示对着一个目标点(投掷/瞄准),用 at。✓ threw a stone at a dog 用石头打狗。✗ to:表去向;✗ for:前往;✗ into:进入里面。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp5','choice','{"stem":"\"It is rude to point ___ people.\"(表示对着某人)","options":["of","at","for","to"],"answer_index":1,"stem_cn":"用手指着别人不礼貌。","explanation_cn":"point at = 指着某人/某物,用 at。✓ point at people 指着别人。✗ to:表去向;✗ for:前往;✗ of:表所属。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp6','choice','{"stem":"\"Where did he go? He went ___ the cinema.\"(回答''去哪儿'',表示去往)","options":["to","at","from","of"],"answer_index":0,"stem_cn":"他去哪儿了?他去了电影院。","explanation_cn":"回答\"去哪儿\"、去往某地,用 to。✓ He went to the cinema 他去了电影院。✗ at:对着一点;✗ of:表所属;✗ from:表来源。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp6','choice','{"stem":"\"Where is Carol? She has just gone ___ the kitchen.\"(回答''在哪儿'',表示进入)","options":["out of","into","at","for"],"answer_index":1,"stem_cn":"卡罗尔在哪儿?她刚进厨房去了。","explanation_cn":"回答\"在哪儿\",进入某空间,用 into。✓ gone into the kitchen 进厨房去了。✗ for:前往;✗ at:对着一点;✗ out of:向外。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp6','choice','{"stem":"\"Which direction did she swim? She swam ___ the shore.\"(回答''朝哪个方向'')","options":["towards","of","at","from"],"answer_index":0,"stem_cn":"她朝哪个方向游?她朝岸边游去。","explanation_cn":"回答\"朝哪个方向\",用 towards。✓ swam towards the shore 朝岸边游去。✗ at:对着一点;✗ of:表所属;✗ from:表来源。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp7','choice','{"stem":"\"___ arriving at the shore, she struggled up the cliff.\"(一到岸边就…,后接动名词)","options":["For","At","On","In"],"answer_index":2,"stem_cn":"一到岸边,她就挣扎着爬上峭壁。","explanation_cn":"on + 动名词表示\"一…就…\"。✓ On arriving at the shore, she struggled up 一到岸边她就往上爬。✗ In / At / For:不构成\"一…就…\"的结构。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp7','choice','{"stem":"\"On ___ home, he called his mother at once.\"(一…就…,介词后接动名词)","options":["to get","getting","got","get"],"answer_index":1,"stem_cn":"一到家,他就给母亲打了电话。","explanation_cn":"介词 on 后面动词用 -ing 形式,表\"一…就…\"。✓ On getting home, he called his mother 一到家他就打电话。✗ get / got:介词后不用原形或过去式;✗ to get:介词后不用不定式。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp8','choice','{"stem":"\"That was all ___ she remembered.\"(引导定语从句修饰 all,可省略)","options":["which one","what","who","that"],"answer_index":3,"stem_cn":"她所记得的就是这些。","explanation_cn":"that 引导定语从句修饰 all,作宾语时可省略。✓ That was all (that) she remembered 她记得的就是这些。✗ what:不能修饰 all;✗ which one / who:不合。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',5,'am2_l33_gp8','choice','{"stem":"\"She climbed toward the light ___ she had seen.\"(引导定语从句修饰 the light)","options":["who","that","what","whose"],"answer_index":1,"stem_cn":"她朝她看到的那盏灯爬去。","explanation_cn":"that 引导定语从句修饰 the light,指物。✓ the light that she had seen 她看到的那盏灯。✗ what:不引导定语从句;✗ who:指人;✗ whose:表所属。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',6,NULL,'choice','{"stem":"美语里\"朝、向\"常写作(不带 s)的形式是:","options":["toward","forward","towards","onward"],"answer_index":0,"explanation_cn":"美语里\"朝、向\"常写作 toward(不带 s);英式写 towards。✓ toward the light 朝灯光。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',6,NULL,'choice','{"stem":"美语说\"住院\"常说(带 the):","options":["at hospital house","in the hospital","on hospital","in hospital"],"answer_index":1,"explanation_cn":"美语说\"住院\"带 the:in the hospital;英式说 in hospital。✓ found herself in the hospital 发现自己躺在医院里。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',6,NULL,'choice','{"stem":"coast 的意思是:","options":["森林","山顶","沙漠","海岸"],"answer_index":3,"explanation_cn":"coast = 海岸。✓ set out from the coast 从海岸出发。\n顺带记:海岸、岸边 = shore;峭壁 = cliff;暴风雨 = storm."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',6,NULL,'choice','{"stem":"struggle 的意思是:","options":["睡觉","微笑","挣扎","休息"],"answer_index":2,"explanation_cn":"struggle = 挣扎。✓ struggled up the cliff 挣扎着爬上峭壁。\n顺带记:解释 = explain;黑暗 = darkness;在前面 = ahead."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',6,NULL,'choice','{"stem":"cliff 的意思是:","options":["山谷","沙滩","小河","峭壁,悬崖"],"answer_index":3,"explanation_cn":"cliff = 峭壁、悬崖。✓ high up on the cliffs 高悬在峭壁上。\n顺带记:岩石、礁石 = rock;海岸 = coast;灯光 = light."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',6,NULL,'choice','{"stem":"explain 的意思是:","options":["命令","解释,叙述","询问","隐瞒"],"answer_index":1,"explanation_cn":"explain = 解释、叙述。✓ able to explain what had happened 能讲述发生的事。\n顺带记:挣扎 = struggle;医院 = hospital;暴风雨 = storm."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',7,NULL,'cloze','{"stem":"第 1 空","context":"One afternoon the girl set out ___1___ the coast and was caught in a storm. The boat struck a rock and she jumped ___2___ the sea. She swam ___3___ the shore all night. ___4___ arriving at the shore, she struggled up the cliff.","blank_no":1,"options":["from","to","at","of"],"answer_index":0,"explanation_cn":"表示从某处出发,用 from。✓ set out from the coast 从海岸出发。\n✗ to:表去向;✗ at:对着一点;✗ of:表所属。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',7,NULL,'cloze','{"stem":"第 2 空","context":"One afternoon the girl set out ___1___ the coast and was caught in a storm. The boat struck a rock and she jumped ___2___ the sea. She swam ___3___ the shore all night. ___4___ arriving at the shore, she struggled up the cliff.","blank_no":2,"options":["into","out of","for","at"],"answer_index":0,"explanation_cn":"表示跳进…里面,用 into。✓ jumped into the sea 跳进海里。\n✗ out of:向外相反;✗ for:前往;✗ at:对着一点。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',7,NULL,'cloze','{"stem":"第 3 空","context":"One afternoon the girl set out ___1___ the coast and was caught in a storm. The boat struck a rock and she jumped ___2___ the sea. She swam ___3___ the shore all night. ___4___ arriving at the shore, she struggled up the cliff.","blank_no":3,"options":["to","from","at","of"],"answer_index":0,"explanation_cn":"表示游到某地,用 to。✓ swam to the shore 游到岸边。\n✗ from:表来源;✗ at:对着一点;✗ of:表所属。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',7,NULL,'cloze','{"stem":"第 4 空","context":"One afternoon the girl set out ___1___ the coast and was caught in a storm. The boat struck a rock and she jumped ___2___ the sea. She swam ___3___ the shore all night. ___4___ arriving at the shore, she struggled up the cliff.","blank_no":4,"options":["On","In","At","For"],"answer_index":0,"explanation_cn":"on + 动名词表示\"一…就…\"。✓ On arriving at the shore 一到岸边。\n✗ In / At / For:不构成\"一…就…\"的结构。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',8,NULL,'choice','{"stem":"What happened to the girl''s boat?","options":["It was very fast","It ran out of fuel","It reached the shore safely","It struck a rock in a storm"],"answer_index":3,"explanation_cn":"课文说 the boat struck a rock,小船在暴风雨中撞上了礁石。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',8,NULL,'choice','{"stem":"How far did the girl swim that night?","options":["Twenty miles","A distance of eight miles","About one mile","She did not swim at all"],"answer_index":1,"explanation_cn":"课文说 she covered a distance of eight miles,那晚她游了8英里。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',8,NULL,'choice','{"stem":"Where did the girl find herself a day later?","options":["At a coast guard station","Back on her boat","In the hospital","On a lonely island"],"answer_index":2,"explanation_cn":"课文说 she found herself in the hospital,第二天她发现自己在医院里。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',9,NULL,'choice','{"stem":"你想说\"她向岸边游去\"(朝…方向用 toward):","options":["She swam toward the shore.","She swam at the shore.","She swam of the shore.","She swam from the shore."],"answer_index":0,"explanation_cn":"\"朝…方向\"用 toward。✓ She swam toward the shore. 场合:说朝某个方向移动。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',9,NULL,'choice','{"stem":"你想说\"我把纸扔到窗外了\"(向外用 out of):","options":["I threw it at the window.","I threw it for the window.","I threw it out of the window.","I threw it into the window."],"answer_index":2,"explanation_cn":"\"向外、到…外面\"用 out of。✓ I threw it out of the window. 场合:说把东西扔到某空间外面。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',9,NULL,'choice','{"stem":"你想说\"她一到岸边就爬上峭壁\"(一…就用 on + 动名词):","options":["On arrived at the shore, she climbed the cliff.","On arrive at the shore, she climbed the cliff.","On to arrive at the shore, she climbed the cliff.","On arriving at the shore, she climbed the cliff."],"answer_index":3,"explanation_cn":"\"一…就…\"用 on + 动名词(动词加 -ing)。✓ On arriving at the shore… 场合:说一件事刚做完就做另一件。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"coast 的意思是:","options":["山顶","森林","海岸","沙漠"],"answer_index":2,"explanation_cn":"coast = 海岸。✓ set out from the coast 从海岸出发。\n顺带记:岸边 = shore;峭壁 = cliff;礁石 = rock."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"struggle 的意思是:","options":["挣扎","睡觉","微笑","休息"],"answer_index":0,"explanation_cn":"struggle = 挣扎。✓ struggled up the cliff 挣扎着爬上峭壁。\n顺带记:解释 = explain;医院 = hospital;黑暗 = darkness."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"\"The girl jumped ___ the sea.\"(表示跳进…里面)","options":["for","at","out of","into"],"answer_index":3,"stem_cn":"姑娘跳进了海里。","explanation_cn":"表示跳进…里面,用 into。✓ jumped into the sea 跳进海里。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"\"He flew ___ Washington last night.\"(表示去往某地)","options":["of","to","from","at"],"answer_index":1,"stem_cn":"昨晚他飞往华盛顿。","explanation_cn":"表示去往某地,用 to。✓ He flew to Washington 他飞往华盛顿。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"\"She swam toward the shore.\" 这句话的意思是:","options":["她游过了岸边。","她在岸边停下。","她向岸边游去。","她从岸边游走。"],"answer_index":2,"explanation_cn":"She swam toward the shore. toward 表\"朝、向\",意思是\"她向岸边游去\"。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"\"On arriving at the shore, she struggled up the cliff.\" 这句话的意思是:","options":["她到岸边前就爬上了峭壁。","她一到岸边就挣扎着爬上峭壁。","她没能到达岸边。","她在岸边睡着了。"],"answer_index":1,"explanation_cn":"On arriving at the shore, she struggled up the cliff. on + 动名词表\"一…就…\",意思是\"她一到岸边就挣扎着爬上峭壁\"。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"Why was the girl in the hospital?","options":["She had been caught in a storm at sea and swam to shore exhausted","She had fallen off a cliff while climbing","She had been in a car accident","She was ill with a fever"],"answer_index":0,"passage":"Nearly a week passed before the girl was able to explain what had happened to her. One afternoon she set out from the coast in a small boat and was caught in a storm. Toward evening, the boat struck a rock and the girl jumped into the sea. Then she swam to shore after spending the whole night in the water. During that time she covered a distance of eight miles. Early next morning, she saw a light ahead. She knew she was near the shore because the light was high up on the cliffs. On arriving at the shore, the girl struggled up the cliff toward the light she had seen. That was all she remembered. When she woke up a day later, she found herself in the hospital.","explanation_cn":"课文说她乘船出海遇上暴风雨,泡了一夜游8英里到岸,精疲力竭,所以进了医院。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"How did the girl know she was near the shore?","options":["She heard people calling","She saw a light high up on the cliffs","She felt the sand under her feet","Her boat had reached land"],"answer_index":1,"passage":"Nearly a week passed before the girl was able to explain what had happened to her. One afternoon she set out from the coast in a small boat and was caught in a storm. Toward evening, the boat struck a rock and the girl jumped into the sea. Then she swam to shore after spending the whole night in the water. During that time she covered a distance of eight miles. Early next morning, she saw a light ahead. She knew she was near the shore because the light was high up on the cliffs. On arriving at the shore, the girl struggled up the cliff toward the light she had seen. That was all she remembered. When she woke up a day later, she found herself in the hospital.","explanation_cn":"课文说 the light was high up on the cliffs,她看到高悬峭壁上的灯光,知道接近岸边。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"Why was the girl in the hospital?","options":["She was caught in a storm and swam eight miles to shore","She fell asleep on the beach","She crashed her boat on purpose","She was attacked at the coast"],"answer_index":0,"audio":"Nearly a week passed before the girl was able to explain what had happened to her. One afternoon she set out from the coast in a small boat and was caught in a storm. Toward evening, the boat struck a rock and the girl jumped into the sea. Then she swam to shore after spending the whole night in the water. During that time she covered a distance of eight miles. Early next morning, she saw a light ahead. She knew she was near the shore because the light was high up on the cliffs. On arriving at the shore, the girl struggled up the cliff toward the light she had seen. That was all she remembered. When she woke up a day later, she found herself in the hospital.","explanation_cn":"课文说她遇上暴风雨、游了8英里到岸,这是她住院的原因。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am2_l33',10,NULL,'choice','{"stem":"What did the girl see early next morning?","options":["Another small boat","A light ahead, high up on the cliffs","Her family on the shore","A passing ship"],"answer_index":1,"audio":"Nearly a week passed before the girl was able to explain what had happened to her. One afternoon she set out from the coast in a small boat and was caught in a storm. Toward evening, the boat struck a rock and the girl jumped into the sea. Then she swam to shore after spending the whole night in the water. During that time she covered a distance of eight miles. Early next morning, she saw a light ahead. She knew she was near the shore because the light was high up on the cliffs. On arriving at the shore, the girl struggled up the cliff toward the light she had seen. That was all she remembered. When she woke up a day later, she found herself in the hospital.","explanation_cn":"课文说 Early next morning, she saw a light ahead… high up on the cliffs,她看到前方峭壁上的灯光。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
